import heapq

def match(orders):
    trades = []
    book = {}  # id -> dict(side, price, qty, ts, active)
    buy_heap = []   # (-price, ts, id)
    sell_heap = []  # (price, ts, id)
    ts_counter = 0

    def process(order_id, side, price, qty, order_type):
        nonlocal ts_counter
        remaining = qty
        if side == 'buy':
            opp_heap = sell_heap
        else:
            opp_heap = buy_heap

        while remaining > 0 and opp_heap:
            top = opp_heap[0]
            resting_id = top[2]
            info = book.get(resting_id)
            if info is None or not info['active']:
                heapq.heappop(opp_heap)
                continue

            resting_price = info['price']

            if order_type != 'market':
                if side == 'buy' and resting_price > price:
                    break
                if side == 'sell' and resting_price < price:
                    break

            trade_qty = min(remaining, info['qty'])
            if side == 'buy':
                trades.append([order_id, resting_id, resting_price, trade_qty])
            else:
                trades.append([resting_id, order_id, resting_price, trade_qty])

            remaining -= trade_qty
            info['qty'] -= trade_qty

            if info['qty'] == 0:
                info['active'] = False
                heapq.heappop(opp_heap)
            else:
                # remaining incoming qty must be zero at this point
                break

        return remaining

    for order in orders:
        typ = order[0]
        if typ == 'cancel':
            oid = order[1]
            info = book.get(oid)
            if info is not None:
                info['active'] = False
            continue

        if typ == 'limit':
            _, oid, side, price, qty = order
            leftover = process(oid, side, price, qty, 'limit')
            if leftover > 0:
                ts = ts_counter
                ts_counter += 1
                info = {'side': side, 'price': price, 'qty': leftover, 'ts': ts, 'active': True}
                book[oid] = info
                if side == 'buy':
                    heapq.heappush(buy_heap, (-price, ts, oid))
                else:
                    heapq.heappush(sell_heap, (price, ts, oid))
            else:
                # fully filled, mark inactive placeholder so cancel does nothing
                book[oid] = {'side': side, 'price': price, 'qty': 0, 'ts': -1, 'active': False}

        elif typ == 'ioc':
            _, oid, side, price, qty = order
            leftover = process(oid, side, price, qty, 'ioc')
            book[oid] = {'side': side, 'price': price, 'qty': leftover, 'ts': -1, 'active': False}

        elif typ == 'market':
            _, oid, side, qty = order
            leftover = process(oid, side, None, qty, 'market')
            book[oid] = {'side': side, 'price': None, 'qty': leftover, 'ts': -1, 'active': False}

    return trades

